js7m1.solucao:
function criarFicha(nome, classe) {
  return { nome, classe, nivel: 1, vida: 100 };
}

function descrever(ficha) {
  return `${ficha.nome}, ${ficha.classe} de nível ${ficha.nivel} (${ficha.vida} de vida)`;
}

function treinar(ficha, atributo, pontos) {
  if (ficha[atributo] === undefined) {
    ficha[atributo] = 0;
  }
  ficha[atributo] += pontos;
}

const ficha = criarFicha("Ana", "maga");
treinar(ficha, "vida", 20);
treinar(ficha, "forca", 5);
console.log(ficha);
console.log(descrever(ficha));

