js7m2.solucao:
function criarPersonagem(nome, vida) {
  return {
    nome,
    vida,
    receberDano(qtd) {
      this.vida -= qtd;
      if (this.vida < 0) {
        this.vida = 0;
      }
      return this.vida;
    },
    estaVivo() {
      return this.vida > 0;
    },
    apresentar() {
      return `${this.nome} (vida: ${this.vida})`;
    },
  };
}

const slime = criarPersonagem("Slime", 30);
console.log(slime.receberDano(12));
console.log(slime.apresentar());
console.log(slime.receberDano(50));
console.log(slime.estaVivo());

