function totalDeItens(mochila) {
  return Object.values(mochila).reduce((soma, qtd) => soma + qtd, 0);
}

function itensAcabando(mochila, minimo) {
  return Object.entries(mochila)
    .filter(([item, qtd]) => qtd < minimo)
    .map(([item]) => item);
}

