function criarInventario(capacidade) {
  return {
    capacidade,
    itens: {},
    total() {
      return Object.values(this.itens).reduce((soma, qtd) => soma + qtd, 0);
    },
    adicionar(nome, qtd) {
      if (this.total() + qtd > this.capacidade) {
        return false;
      }
      this.itens[nome] = (this.itens[nome] || 0) + qtd;
      return true;
    },
    remover(nome, qtd) {
      const tem = this.itens[nome] || 0;
      if (tem < qtd) {
        return false;
      }
      this.itens[nome] = tem - qtd;
      if (this.itens[nome] === 0) {
        delete this.itens[nome];
      }
      return true;
    },
    listar() {
      return Object.entries(this.itens)
        .sort((a, b) => a[0].localeCompare(b[0]))
        .map(([nome, qtd]) => `${nome} x${qtd}`);
    },
  };
}

function carregarInventario(texto) {
  const dados = JSON.parse(texto);
  const inv = criarInventario(dados.capacidade);
  inv.itens = { ...dados.itens };
  return inv;
}

